engine/bridge.py:
"""In-browser bridge: the REST API's routes as a plain function call.

The GitHub Pages demo runs this engine inside the visitor's browser with Pyodide
(Python compiled to WebAssembly). There is no server there, so the web console sends
its requests to `dispatch()` instead of over HTTP. Same engine code, same JSON.
"""

from __future__ import annotations

import base64
import json
import re
from pathlib import Path
from typing import Any
from urllib.parse import parse_qs, unquote, urlsplit

from pydantic import BaseModel, ValidationError

from .config import Settings
from .core import Conflict, Engine, Forbidden, NotFound
from .gateway import ProviderError, list_providers
from .ingest import IngestError
from .schemas import AnswersIn, ProjectIn, ReviewIn, RunIn, TextArtifactIn

EXAMPLES = Path(__file__).resolve().parent.parent / "examples" / "clinic_intake"
ACTOR = "demo"

_engine: Engine | None = None


def engine() -> Engine:
    global _engine
    if _engine is None:
        _engine = Engine(Settings(db_path=":memory:"))
    return _engine


def _body(model: type[BaseModel], body: Any) -> Any:
    return model.model_validate(body if body is not None else {})


def _route(method: str, path: str, query: dict[str, str], body: Any) -> Any:
    e = engine()
    m = re.fullmatch

    if method == "GET" and path == "/api/health":
        return {"status": "ok", "provider": "offline", "embedder": "in-browser", "auth": False}
    if method == "GET" and path == "/api/providers":
        return [p for p in list_providers(e.settings) if p["name"] == "offline"]
    if method == "GET" and path == "/api/me":
        return {"actor": ACTOR, "role": "approver"}
    if path == "/api/projects":
        if method == "GET":
            return e.store.list_projects()
        return e.create_project(_body(ProjectIn, body).name, ACTOR)

    if g := m(r"/api/projects/([\w-]+)/artifacts", path):
        pid = g.group(1)
        if method == "GET":
            e.project(pid)
            return e.store.list_artifacts(pid)
        results = []
        for f in (body or {}).get("files", []):
            try:
                results.append(e.ingest_bytes(pid, f["name"], base64.b64decode(f["b64"]), ACTOR))
            except IngestError as exc:
                results.append({"filename": f["name"], "error": str(exc)})
        return results
    if (g := m(r"/api/projects/([\w-]+)/artifacts/text", path)) and method == "POST":
        b = _body(TextArtifactIn, body)
        return e.ingest_text(g.group(1), b.filename, b.text, ACTOR)
    if (g := m(r"/api/projects/([\w-]+)/sample", path)) and method == "POST":
        return [e.ingest_bytes(g.group(1), p.name, p.read_bytes(), ACTOR) for p in sorted(EXAMPLES.iterdir())]
    if (g := m(r"/api/projects/([\w-]+)/search", path)) and method == "GET":
        q = query.get("q", "").strip()
        if not q:
            raise Conflict("Search query is empty")
        return e.search(g.group(1), q, max(1, min(int(query.get("k", 8)), 25)))
    if g := m(r"/api/projects/([\w-]+)/runs", path):
        pid = g.group(1)
        if method == "GET":
            e.project(pid)
            return e.store.list_runs(pid)
        return e.start_run(pid, ACTOR, _body(RunIn, body).provider)

    if (g := m(r"/api/chunks/(.+)", path)) and method == "GET":
        return e.chunk(g.group(1))
    if (g := m(r"/api/runs/([\w-]+)", path)) and method == "GET":
        return e.run(g.group(1))
    if (g := m(r"/api/runs/([\w-]+)/answers", path)) and method == "POST":
        return e.answer(g.group(1), _body(AnswersIn, body).answers, ACTOR)
    if (g := m(r"/api/runs/([\w-]+)/review", path)) and method == "POST":
        b = _body(ReviewIn, body)
        return e.review(g.group(1), b.decision, b.note, ACTOR)
    if (g := m(r"/api/runs/([\w-]+)/events", path)) and method == "GET":
        return e.events(g.group(1))
    if (g := m(r"/api/runs/([\w-]+)/export\.md", path)) and method == "GET":
        return e.export_markdown(g.group(1))
    raise NotFound(f"No route for {method} {path}")


def dispatch(method: str, url: str, body_json: str = "null") -> str:
    """Handle one request. Returns JSON: {"status": int, "data": ...}."""
    parts = urlsplit(url)
    path = unquote(parts.path)
    query = {k: v[-1] for k, v in parse_qs(parts.query).items()}
    try:
        data = _route(method.upper(), path, query, json.loads(body_json))
        status = 200
    except NotFound as exc:
        status, data = 404, {"detail": str(exc)}
    except Forbidden as exc:
        status, data = 403, {"detail": str(exc)}
    except (IngestError, ValidationError) as exc:  # both subclass ValueError, so they come first
        status, data = 422, {"detail": str(exc)}
    except (Conflict, ValueError) as exc:  # ValueError covers bad numbers in the query string
        status, data = 409, {"detail": str(exc)}
    except ProviderError as exc:
        status, data = 400, {"detail": str(exc)}
    return json.dumps({"status": status, "data": data})

engine/core.py:
"""The engine itself. The REST API, MCP server and CLI are thin wrappers around this class.

Run lifecycle:
    ingest -> build context -> generate spec --(open questions?)--> needs_answers
                                   ^                                    | answers
                                   |------------------------------------+
                                   |                                    v
                         request_changes <---- reviewer ---------- in_review --> approved
"""

from __future__ import annotations

from typing import Any

from .config import Settings, get_settings
from .gateway import ProviderError, get_embedder, get_provider, is_configured
from .index import IndexCache
from .ingest import IngestError, chunk, extract_text, safe_filename, sha256
from .schemas import RunStatus, Spec
from .spec import GenerationResult, llm_spec, offline_spec
from .store import Store

# Retrieval queries used to build context for a spec, one per section of the spec.
CONTEXT_QUERIES = [
    "goal purpose of the app what we want to build",
    "users roles staff who uses it needs to",
    "must should need to be able to requirements features",
    "track store record data fields form",
    "screen page dashboard view",
    "security privacy compliance HIPAA login access",
    "offline language tablet integration deadline budget",
    "not sure unclear TBD open question decide",
]


class NotFound(LookupError):
    pass


class Conflict(RuntimeError):
    pass


class Forbidden(PermissionError):
    pass


class Engine:
    def __init__(self, settings: Settings | None = None, store: Store | None = None) -> None:
        self.settings = settings or get_settings()
        self.store = store or Store(self.settings.db_path)
        self.embedder = get_embedder(self.settings)
        self.indexes = IndexCache()

    # ---------- projects ----------

    def create_project(self, name: str, actor: str) -> dict[str, Any]:
        project = self.store.create_project(name)
        self.store.log(project["id"], actor, "project_created", name=name)
        return project

    def project(self, project_id: str) -> dict[str, Any]:
        project = self.store.get_project(project_id)
        if not project:
            raise NotFound(f"Project {project_id} not found")
        return project

    # ---------- ingest ----------

    def ingest_bytes(self, project_id: str, filename: str, data: bytes, actor: str) -> dict[str, Any]:
        self.project(project_id)
        if len(data) > self.settings.max_upload_bytes:
            raise IngestError(f"{filename} is larger than {self.settings.max_upload_bytes // 1024 // 1024} MB")
        filename = safe_filename(filename)
        kind, text = extract_text(filename, data)
        return self._store_text(project_id, filename, kind, text, actor)

    def ingest_text(self, project_id: str, filename: str, text: str, actor: str) -> dict[str, Any]:
        self.project(project_id)
        filename = safe_filename(filename)
        if "." not in filename:
            filename += ".md"
        kind, clean = extract_text(filename, text.encode("utf-8"))
        return self._store_text(project_id, filename, kind, clean, actor)

    def _store_text(self, project_id: str, filename: str, kind: str, text: str, actor: str) -> dict[str, Any]:
        digest = sha256(text)
        dup = self.store.find_artifact_by_hash(project_id, digest)
        if dup:
            return {**dup, "duplicate": True}
        pieces = chunk(text, self.settings.chunk_words, self.settings.chunk_overlap)
        art = self.store.add_artifact(project_id, filename, kind, digest, text, pieces, actor)
        self.store.log(project_id, actor, "artifact_ingested", artifact=art["id"], filename=filename, chunks=len(pieces))
        art.pop("text", None)
        return art

    # ---------- retrieval ----------

    def _index(self, project_id: str):
        return self.indexes.get(project_id, self.store.list_chunks(project_id), self.embedder)

    def search(self, project_id: str, query: str, k: int = 8) -> list[dict[str, Any]]:
        self.project(project_id)
        return [h.as_dict() for h in self._index(project_id).search(query, k)]

    def build_context(self, project_id: str, run: dict[str, Any]) -> list[dict[str, Any]]:
        """Pick the passages the spec is written from, plus answers and reviewer feedback."""
        index = self._index(project_id)
        limit = self.settings.context_chunks
        if len(index.chunks) <= limit:
            chosen = list(index.chunks)
        else:
            seen: dict[str, dict] = {}
            per_query = max(2, limit // len(CONTEXT_QUERIES) + 1)
            for q in CONTEXT_QUERIES:
                for hit in index.search(q, per_query):
                    seen.setdefault(hit.chunk_id, {"id": hit.chunk_id, "filename": hit.filename, "text": hit.text})
            order = {c["id"]: i for i, c in enumerate(index.chunks)}
            chosen = sorted(list(seen.values())[:limit], key=lambda c: order[c["id"]])
        for qid, qa in run["answers"].items():
            chosen.append({"id": f"answers#{qid}", "filename": "answers", "text": f"Q: {qa['question']}\nA: {qa['answer']}"})
        for i, note in enumerate(run["feedback"]):
            chosen.append({"id": f"feedback#{i}", "filename": "reviewer feedback", "text": note["note"]})
        return chosen

    # ---------- runs ----------

    def start_run(self, project_id: str, actor: str, provider: str | None = None) -> dict[str, Any]:
        project = self.project(project_id)
        if not self.store.list_chunks(project_id):
            raise Conflict("Add at least one artifact before generating a spec")
        provider = (provider or self.settings.provider).lower()
        get_provider(provider, self.settings)  # validates the name early
        run = self.store.create_run(project_id, provider, actor)
        self.store.log(project_id, actor, "run_started", run["id"], provider=provider)
        return self._generate(project, run, actor)

    def _generate(self, project: dict, run: dict[str, Any], actor: str) -> dict[str, Any]:
        context = self.build_context(project["id"], run)
        self.store.log(
            project["id"], "engine", "context_built", run["id"],
            passages=len(context), chunk_ids=[c["id"] for c in context][:40],
        )
        answered = {qid: qa["answer"] for qid, qa in run["answers"].items()}
        question_text = {qid: qa["question"] for qid, qa in run["answers"].items()}
        warnings: list[str] = []
        result: GenerationResult
        provider_name = run["provider"]
        llm = None
        if provider_name != "offline":
            if not is_configured(provider_name, self.settings):
                warnings.append(f"{provider_name} is not configured, so the offline extractor was used instead.")
            else:
                llm = get_provider(provider_name, self.settings)
        try:
            if llm is not None:
                result = llm_spec(llm, project["name"], context, answered, question_text, self.settings.max_spec_repairs)
            else:
                result = GenerationResult(spec=offline_spec(project["name"], context, answered))
        except ProviderError as exc:
            warnings.append(f"{provider_name} failed ({exc}); the offline extractor was used instead.")
            self.store.log(project["id"], "engine", "provider_fallback", run["id"], error=str(exc)[:300])
            result = GenerationResult(spec=offline_spec(project["name"], context, answered))

        spec: Spec = result.spec
        warnings.extend(result.warnings)
        status = RunStatus.needs_answers if spec.open_questions else RunStatus.in_review
        updated = self.store.update_run(
            run["id"], spec=spec.model_dump(), status=status.value, warnings=warnings
        )
        self.store.log(
            project["id"], "engine", "spec_generated", run["id"],
            revision=updated["revision"], repairs=result.repairs, status=status.value,
            features=len(spec.features), open_questions=len(spec.open_questions), warnings=len(warnings),
        )
        return updated

    def run(self, run_id: str) -> dict[str, Any]:
        run = self.store.get_run(run_id)
        if not run:
            raise NotFound(f"Run {run_id} not found")
        return run

    def answer(self, run_id: str, answers: dict[str, str], actor: str) -> dict[str, Any]:
        run = self.run(run_id)
        if run["status"] == RunStatus.approved.value:
            raise Conflict("This spec is already approved")
        open_q = {q["id"]: q["question"] for q in (run["spec"] or {}).get("open_questions", [])}
        unknown = set(answers) - set(open_q)
        if unknown:
            raise Conflict(f"Unknown or already answered question ids: {', '.join(sorted(unknown))}")
        clean = {k: v.strip() for k, v in answers.items() if v and v.strip()}
        if not clean:
            raise Conflict("Answers cannot be empty")
        merged = {**run["answers"], **{k: {"question": open_q[k], "answer": v} for k, v in clean.items()}}
        self.store.update_run(run_id, answers=merged, revision=run["revision"] + 1)
        self.store.log(run["project_id"], actor, "questions_answered", run_id, ids=sorted(clean))
        return self._generate(self.project(run["project_id"]), self.run(run_id), actor)

    def review(self, run_id: str, decision: str, note: str, actor: str) -> dict[str, Any]:
        run = self.run(run_id)
        if run["status"] != RunStatus.in_review.value:
            raise Conflict(f"Only specs in review can be reviewed (status is {run['status']})")
        if self.settings.auth_enabled and actor == run["created_by"]:
            raise Forbidden("Separation of duties: the person who started a run cannot approve it")
        if decision == "approve":
            updated = self.store.update_run(run_id, status=RunStatus.approved.value, approved_by=actor)
            self.store.log(run["project_id"], actor, "spec_approved", run_id, revision=run["revision"], note=note)
            return updated
        if not note.strip():
            raise Conflict("Say what should change when requesting changes")
        feedback = [*run["feedback"], {"by": actor, "note": note.strip()}]
        self.store.update_run(run_id, feedback=feedback, revision=run["revision"] + 1)
        self.store.log(run["project_id"], actor, "changes_requested", run_id, note=note)
        return self._generate(self.project(run["project_id"]), self.run(run_id), actor)

    def events(self, run_id: str) -> list[dict[str, Any]]:
        run = self.run(run_id)
        return self.store.events(run["project_id"], run_id)

    def chunk(self, chunk_id: str) -> dict[str, Any]:
        found = self.store.get_chunk(chunk_id)
        if not found:
            raise NotFound(f"Passage {chunk_id} not found")
        return found

    # ---------- export ----------

    def export_markdown(self, run_id: str) -> str:
        run = self.run(run_id)
        spec = run["spec"] or {}

        def cite(item: dict) -> str:
            refs = sorted({s["artifact"] or s["chunk_id"] for s in item.get("sources", [])})
            return f" _(sources: {', '.join(refs)})_" if refs else ""

        status = run["status"].replace("_", " ")
        lines = [f"# {spec.get('title', 'Spec')}", ""]
        if run["status"] != RunStatus.approved.value:
            lines += [f"> **DRAFT** (status: {status}, revision {run['revision']})", ""]
        else:
            lines += [f"> Approved by {run['approved_by']} (revision {run['revision']})", ""]
        lines += [spec.get("summary", ""), ""]
        sections = [
            ("Users", "users", lambda u: f"- **{u['name']}**" + (": " + "; ".join(u["goals"]) if u["goals"] else "") + cite(u)),
            ("Features", "features", lambda f: f"- **{f['id']} {f['name']}** [{f['priority']}]: {f['description']}{cite(f)}"),
            ("Data entities", "entities", lambda e: f"- **{e['name']}**" + (f" ({', '.join(e['fields'])})" if e["fields"] else "") + cite(e)),
            ("Screens", "screens", lambda s: f"- **{s['name']}**: {s['purpose']}{cite(s)}"),
            ("Constraints", "constraints", lambda c: f"- [{c['kind']}] {c['text']}{cite(c)}"),
            ("Open questions", "open_questions", lambda q: f"- {q['question']}"),
        ]
        for heading, key, fmt in sections:
            items = spec.get(key) or []
            if items:
                lines += [f"## {heading}", "", *[fmt(i) for i in items], ""]
        if run["answers"]:
            lines += ["## Decisions", ""]
            for qa in run["answers"].values():
                lines.append(f"- **{qa['question']}** {qa['answer']}")
            lines.append("")
        return "\n".join(lines)

engine/gateway.py:
"""Model gateway: one interface for cloud and local models.

Engine code asks the gateway for "JSON from this prompt" and never imports a vendor SDK,
so switching OpenAI -> Anthropic -> a local Gemma model on Ollama is a config change.
The `offline` provider uses no model at all (rule-based extraction), which keeps the
public demo free and lets the engine run fully air-gapped.
"""

from __future__ import annotations

import os
from collections.abc import Callable, Sequence
from typing import Protocol

from .config import Settings
from .index import Embedder, HashingEmbedder


class ProviderError(RuntimeError):
    pass


class LLMProvider(Protocol):
    name: str
    model: str

    def complete_json(self, system: str, user: str) -> str: ...


def _post(url: str, headers: dict, payload: dict) -> dict:
    import httpx  # imported lazily so the offline engine also runs in the browser (Pyodide)

    try:
        resp = httpx.post(url, headers=headers, json=payload, timeout=httpx.Timeout(90.0, connect=10.0))
    except httpx.HTTPError as exc:
        raise ProviderError(f"Could not reach {url}: {exc}") from exc
    if resp.status_code >= 400:
        raise ProviderError(f"{url} returned {resp.status_code}: {resp.text[:300]}")
    return resp.json()


class OpenAIProvider:
    name = "openai"

    def __init__(self, settings: Settings) -> None:
        self.model = settings.openai_model
        self.key = os.environ.get("OPENAI_API_KEY", "")
        self.base = os.environ.get("OPENAI_BASE_URL", "https://api.openai.com/v1").rstrip("/")

    def complete_json(self, system: str, user: str) -> str:
        data = _post(
            f"{self.base}/chat/completions",
            {"Authorization": f"Bearer {self.key}"},
            {
                "model": self.model,
                "temperature": 0.1,
                "response_format": {"type": "json_object"},
                "messages": [{"role": "system", "content": system}, {"role": "user", "content": user}],
            },
        )
        return data["choices"][0]["message"]["content"]


class AnthropicProvider:
    name = "anthropic"

    def __init__(self, settings: Settings) -> None:
        self.model = settings.anthropic_model
        self.key = os.environ.get("ANTHROPIC_API_KEY", "")

    def complete_json(self, system: str, user: str) -> str:
        if not self.model:
            raise ProviderError("Set ANTHROPIC_MODEL to the Anthropic model id you want to use")
        data = _post(
            "https://api.anthropic.com/v1/messages",
            {"x-api-key": self.key, "anthropic-version": "2023-06-01"},
            {
                "model": self.model,
                "max_tokens": 4096,
                "temperature": 0.1,
                "system": system + "\nRespond with a single JSON object and nothing else.",
                "messages": [{"role": "user", "content": user}],
            },
        )
        return "".join(block.get("text", "") for block in data.get("content", []))


class OllamaProvider:
    """Local models (e.g. Gemma, Llama) for offline or air-gapped deployments."""

    name = "ollama"

    def __init__(self, settings: Settings) -> None:
        self.model = settings.ollama_model
        self.url = settings.ollama_url

    def complete_json(self, system: str, user: str) -> str:
        data = _post(
            f"{self.url}/api/chat",
            {},
            {
                "model": self.model,
                "format": "json",
                "stream": False,
                "options": {"temperature": 0.1},
                "messages": [{"role": "system", "content": system}, {"role": "user", "content": user}],
            },
        )
        return data["message"]["content"]


# Registry so tests (or plugins) can add providers without touching engine code.
PROVIDERS: dict[str, Callable[[Settings], LLMProvider]] = {
    "openai": OpenAIProvider,
    "anthropic": AnthropicProvider,
    "ollama": OllamaProvider,
}


def is_configured(name: str, settings: Settings) -> bool:
    if name == "offline":
        return True
    if name == "openai":
        return bool(os.environ.get("OPENAI_API_KEY"))
    if name == "anthropic":
        return bool(os.environ.get("ANTHROPIC_API_KEY") and settings.anthropic_model)
    if name == "ollama":
        return bool(os.environ.get("OLLAMA_URL"))
    return name in PROVIDERS


def get_provider(name: str, settings: Settings) -> LLMProvider | None:
    """Return the LLM provider, or None for the rule-based offline provider."""
    name = name.lower()
    if name == "offline":
        return None
    if name not in PROVIDERS:
        raise ProviderError(f"Unknown provider {name!r}. Choose from: offline, {', '.join(PROVIDERS)}")
    return PROVIDERS[name](settings)


def list_providers(settings: Settings) -> list[dict]:
    models = {
        "offline": "rule-based extractor",
        "openai": settings.openai_model,
        "anthropic": settings.anthropic_model or "set ANTHROPIC_MODEL",
        "ollama": settings.ollama_model,
    }
    names = ["offline", *PROVIDERS]
    return [
        {
            "name": n,
            "model": models.get(n, "custom"),
            "configured": is_configured(n, settings),
            "default": n == settings.provider,
        }
        for n in names
    ]


# ---------- embedders ----------


class OpenAIEmbedder:
    def __init__(self, settings: Settings) -> None:
        self.model = settings.openai_embed_model
        self.name = f"openai:{self.model}"
        self.key = os.environ.get("OPENAI_API_KEY", "")
        self.base = os.environ.get("OPENAI_BASE_URL", "https://api.openai.com/v1").rstrip("/")

    def embed(self, texts: Sequence[str]) -> list[list[float]]:
        out: list[list[float]] = []
        for i in range(0, len(texts), 96):
            data = _post(
                f"{self.base}/embeddings",
                {"Authorization": f"Bearer {self.key}"},
                {"model": self.model, "input": list(texts[i : i + 96])},
            )
            out.extend(item["embedding"] for item in sorted(data["data"], key=lambda d: d["index"]))
        return out


class OllamaEmbedder:
    def __init__(self, settings: Settings) -> None:
        self.model = settings.ollama_embed_model
        self.name = f"ollama:{self.model}"
        self.url = settings.ollama_url

    def embed(self, texts: Sequence[str]) -> list[list[float]]:
        data = _post(f"{self.url}/api/embed", {}, {"model": self.model, "input": list(texts)})
        return data["embeddings"]


def get_embedder(settings: Settings) -> Embedder:
    if settings.embedder == "openai":
        return OpenAIEmbedder(settings)
    if settings.embedder == "ollama":
        return OllamaEmbedder(settings)
    return HashingEmbedder()

engine/index.py:
"""Hybrid retrieval: BM25 keyword search + dense vectors, merged with Reciprocal Rank Fusion.

Keyword search catches exact terms ("HIPAA", "intake form"); vectors catch paraphrases
("sign-in sheet" vs "check-in"). RRF combines the two rankings without having to tune
score scales against each other.
"""

from __future__ import annotations

import hashlib
import math
import re
import threading
from collections import Counter
from collections.abc import Sequence
from dataclasses import dataclass
from typing import Protocol

STOPWORDS = frozenset(
    """a an and are as at be been but by can could do does for from had has have he her his i if in into
    is it its me my no not of on or our she so than that the their them then there these they this to
    too up us was we were what when where which who will with would you your just also very really""".split()
)

_WORD = re.compile(r"[a-z0-9]+(?:'[a-z]+)?")


def _stem(word: str) -> str:
    """Tiny suffix stripper: enough to match nurse/nurses, track/tracking, entry/entries."""
    if word.endswith(("sses", "ches", "shes", "xes", "zes")) and len(word) > 5:
        return word[:-2]
    for suffix in ("ations", "ation", "ings", "ing", "ies", "edly", "ed", "s"):
        if word.endswith(suffix) and len(word) - len(suffix) >= 3 and not word.endswith("ss"):
            return word[: -len(suffix)] + ("y" if suffix == "ies" else "")
    return word


def tokenize(text: str) -> list[str]:
    return [_stem(w) for w in _WORD.findall(text.lower()) if w not in STOPWORDS and len(w) > 1]


class Embedder(Protocol):
    name: str

    def embed(self, texts: Sequence[str]) -> list[list[float]]: ...


class HashingEmbedder:
    """Local, deterministic embeddings via feature hashing of unigrams and bigrams.

    No model download and no API cost, so the demo runs anywhere (including air-gapped).
    Swap in OpenAI or Ollama embeddings with ENGINE_EMBEDDER for better semantic recall.
    """

    name = "hashing-512"

    def __init__(self, dim: int = 512) -> None:
        self.dim = dim

    def _bucket(self, feature: str) -> tuple[int, float]:
        h = int.from_bytes(hashlib.blake2b(feature.encode(), digest_size=8).digest(), "big")
        return h % self.dim, (1.0 if (h >> 63) & 1 else -1.0)

    def embed(self, texts: Sequence[str]) -> list[list[float]]:
        out = []
        for text in texts:
            toks = tokenize(text)
            feats = Counter(toks + [f"{a}_{b}" for a, b in zip(toks, toks[1:], strict=False)])
            vec = [0.0] * self.dim
            for feat, tf in feats.items():
                idx, sign = self._bucket(feat)
                vec[idx] += sign * (1.0 + math.log(tf))
            norm = math.sqrt(sum(v * v for v in vec)) or 1.0
            out.append([v / norm for v in vec])
        return out


def _cosine(a: Sequence[float], b: Sequence[float]) -> float:
    dot = sum(x * y for x, y in zip(a, b, strict=True))
    na = math.sqrt(sum(x * x for x in a)) or 1.0
    nb = math.sqrt(sum(y * y for y in b)) or 1.0
    return dot / (na * nb)


@dataclass
class Hit:
    chunk_id: str
    filename: str
    text: str
    score: float
    bm25_rank: int | None
    vector_rank: int | None

    def as_dict(self) -> dict:
        return self.__dict__.copy()


class HybridIndex:
    def __init__(self, chunks: list[dict], embedder: Embedder, k1: float = 1.5, b: float = 0.75) -> None:
        self.chunks = chunks
        self.embedder = embedder
        self.k1, self.b = k1, b
        self.tokens = [tokenize(c["text"]) for c in chunks]
        self.tf = [Counter(t) for t in self.tokens]
        self.avgdl = (sum(len(t) for t in self.tokens) / len(self.tokens)) if self.tokens else 0.0
        df: Counter[str] = Counter()
        for t in self.tokens:
            df.update(set(t))
        n = len(chunks)
        self.idf = {term: math.log(1 + (n - d + 0.5) / (d + 0.5)) for term, d in df.items()}
        self.vectors = embedder.embed([c["text"] for c in chunks]) if chunks else []

    def _bm25(self, query: str) -> list[tuple[int, float]]:
        q = tokenize(query)
        scores = []
        for i, tf in enumerate(self.tf):
            dl = len(self.tokens[i])
            s = 0.0
            for term in q:
                f = tf.get(term)
                if not f:
                    continue
                s += self.idf[term] * f * (self.k1 + 1) / (f + self.k1 * (1 - self.b + self.b * dl / (self.avgdl or 1)))
            if s > 0:
                scores.append((i, s))
        return sorted(scores, key=lambda x: -x[1])

    def _dense(self, query: str) -> list[tuple[int, float]]:
        if not self.vectors:
            return []
        qv = self.embedder.embed([query])[0]
        scores = [(i, _cosine(qv, v)) for i, v in enumerate(self.vectors)]
        return sorted((s for s in scores if s[1] > 0.05), key=lambda x: -x[1])

    def search(self, query: str, k: int = 8, rrf_k: int = 60) -> list[Hit]:
        if not self.chunks or not query.strip():
            return []
        bm25 = self._bm25(query)
        dense = self._dense(query)
        fused: dict[int, float] = {}
        b_rank = {i: r for r, (i, _) in enumerate(bm25, 1)}
        v_rank = {i: r for r, (i, _) in enumerate(dense, 1)}
        for ranks in (b_rank, v_rank):
            for i, r in ranks.items():
                fused[i] = fused.get(i, 0.0) + 1.0 / (rrf_k + r)
        top = sorted(fused.items(), key=lambda x: -x[1])[:k]
        best = top[0][1] if top else 1.0
        return [
            Hit(
                chunk_id=self.chunks[i]["id"],
                filename=self.chunks[i]["filename"],
                text=self.chunks[i]["text"],
                score=round(s / best, 3),
                bm25_rank=b_rank.get(i),
                vector_rank=v_rank.get(i),
            )
            for i, s in top
        ]


class IndexCache:
    """Rebuilds a project's index only when its chunks change."""

    def __init__(self) -> None:
        self._cache: dict[str, tuple[tuple, HybridIndex]] = {}
        self._lock = threading.Lock()

    def get(self, project_id: str, chunks: list[dict], embedder: Embedder) -> HybridIndex:
        key = (embedder.name, len(chunks), chunks[-1]["id"] if chunks else None)
        with self._lock:
            cached = self._cache.get(project_id)
            if cached and cached[0] == key:
                return cached[1]
        index = HybridIndex(chunks, embedder)
        with self._lock:
            self._cache[project_id] = (key, index)
        return index

